ROOT=g.ROOT; OUT=g.OUT
g.STYLES['body'].fontSize=10.8;g.STYLES['body'].leading=15.2;g.STYLES['body'].spaceAfter=7
g.STYLES['title'].fontSize=26;g.STYLES['title'].leading=30;g.STYLES['title'].spaceAfter=11
g.STYLES['h2'].spaceAfter=6;g.STYLES['table'].fontSize=9.6;g.STYLES['table'].leading=12.8
JOBS=['Reader','Investigator','Recorder','Checker']
TEAM=[['2','Person 1: Reader + Recorder. Person 2: Investigator + Checker. Exchange both bundles after each checkpoint.'],['3','Reader; Investigator; Recorder + Checker. Pass the three bundles clockwise after each checkpoint.'],['4','One job each. Pass all four jobs clockwise after each checkpoint.'],['5','Reader pair, one Investigator, one Recorder, one Checker. Reader pair: one reads, the other points to the evidence; swap next checkpoint.'],['6','Reader pair, Investigator pair, one Recorder, one Checker. Investigator pair: one moves/chooses, the other rejects a wrong choice; swap next checkpoint.']]

def text(s,style='body'): return g.p(s,style)
def page(title,sub=''): return [text(sub,'eyebrow'),text(title,'title'),g.gap(10)]
def numbered(items): return [text(f'<b>{i+1}.</b> '+s) for i,s in enumerate(items)]
def table(heads,rows,w): return g.grid(heads,rows,[w/len(heads)]*len(heads))
def cards(items,w,height=95):
 t=cutgrid(items,w,2,height)
 if len(items)%2: t._cellvalues[-1][-1]=g.p('SPARE SPACE / not a game card','small')
 return t

class ResultBoard(Flowable):
 def __init__(self,w): super().__init__();self.width=w;self.height=290
 def draw(self):
  c=self.canv;c.setStrokeColor(g.LINE);c.setFillColor(g.NAVY)
  for i in range(5):
   y=245-i*49;c.roundRect(0,y,self.width,42,5,stroke=1,fill=0);c.setFont('ArialBold',10);c.drawString(12,y+25,f'{i+1} / Discovery');c.setFont('Arial',9);c.drawString(12,y+9,'Result: __________________  Evidence: __________________________')

class WorkSpace(Flowable):
 def __init__(self,w,st): super().__init__();self.width=w;self.height=80;self.st=st
 def draw(self):
  c=self.canv;c.setStrokeColor(g.LINE);c.setFillColor(g.NAVY);c.setFont('ArialBold',10)
  c.drawString(0,70,'TEAM WORK SPACE / point, draw or write')
  route='From' in self.st['heads'] and 'To' in self.st['heads']
  if route:
   bw=(self.width-36)/4
   for i in range(4):
    x=i*(bw+12);c.roundRect(x,22,bw,30,4,stroke=1,fill=0)
    if i<3:c.drawString(x+bw+2,36,'>')
   c.setFont('Arial',9);c.drawString(0,5,'Rejected branch / why it stops: ______________________________________')
  else:
   c.setFont('Arial',9)
   for i,label in enumerate(['A fact we checked','A choice we rejected','Why it failed']):
    y=48-i*20;c.drawString(0,y,label+':');c.line(140,y-2,self.width,y-2)

class DinosaurProps(Flowable):
 def __init__(self,w,st,checkpoint): super().__init__();self.width=w;self.height=350;self.st=st;self.checkpoint=checkpoint
 def draw(self):
  c=self.canv;cw=self.width/2;ch=175
  for i,row in enumerate(self.st['rows']):
   x=(i%2)*cw;y=(1-i//2)*ch;c.setStrokeColor(g.LINE);c.setFillColor(g.PALE);c.rect(x,y,cw,ch,fill=1,stroke=1)
   c.setFillColor(g.NAVY);c.setFont('ArialBold',11);c.drawString(x+12,y+ch-21,f'{self.checkpoint} / TEAM / {row[0]}')
   c.setFont('Arial',10.5)
   for j,(key,value) in enumerate(zip(self.st['heads'][1:],row[1:])):c.drawString(x+12,y+ch-42-j*16,f'{key}: {value}')
   # Outline drawings repeat the words; both work in greyscale.
   cx=x+cw-60;cy=y+45;c.setStrokeColor(g.NAVY);c.setFillColor(g.NAVY);c.setLineWidth(1.4)
   if self.checkpoint==1:
    toes=int(row[1]);
    for j in range(toes):c.circle(cx-19+j*19,cy+28,6,fill=0,stroke=1)
    if row[2]=='ROUND':c.ellipse(cx-28,cy-21,cx+28,cy+17,fill=0,stroke=1)
    else:
     path=c.beginPath();path.moveTo(cx-28,cy+12);path.lineTo(cx+28,cy+12);path.lineTo(cx,cy-23);path.close();c.drawPath(path,fill=0,stroke=1)
    if row[3]=='ONE':
     c.setFillColor(g.PALE);c.rect(cx+21,cy-6,9,15,fill=1,stroke=0);c.setStrokeColor(g.NAVY);c.line(cx+26,cy+8,cx+12,cy);c.line(cx+12,cy,cx+26,cy-6)
   else:
    c.roundRect(cx-27,cy-22,54,50,7,fill=0,stroke=1)
    for j in range(int(row[2])):c.line(cx-12+j*20,cy+28,cx-12+j*20,cy+42)
    if row[3]=='TRIANGLE':
     path=c.beginPath();path.moveTo(cx,cy+13);path.lineTo(cx-11,cy-7);path.lineTo(cx+11,cy-7);path.close();c.drawPath(path,fill=0,stroke=1)
    else:c.circle(cx,cy+2,10,fill=0,stroke=1)

def normalise(s):
 # Fixed clues and candidates are never generated by AI.
 for st in s['stages']:
  st.setdefault('role_cards',[]);st.setdefault('prompts',['Our answer']);st.setdefault('why',st['answer']+' agrees with every printed condition.');st.setdefault('extra','')
 return s

def actions(st,i):
 if st.get('actions'): return st['actions']
 heads=' '.join(st['heads']).lower(); story=st['story'].lower()
 if 'from' in heads and 'to' in heads:
  act=['Place the previous start result above the cards. Investigator finds every strip beginning there.','Join an end place to the same start place on another strip. Lay the chain left to right; try each branch.','Keep only the chain reaching the destination required in the mission. Checker explains why the other branch stops.','Recorder copies the strip letters in order and the final place; everybody traces the chain aloud.']
 elif re.search(r'\border\b|\bclockwise\b|\bfirst\b', story):
  act=['Read the complete ordering rule, including first/last or position words.','Investigator lays out or points to the pieces in that order. Read from the stated starting position.','Checker tests every ordering condition, one at a time; rearrange if a condition fails.','Recorder writes the whole sequence, including repeated symbols if the rule requires them.']
 elif i==4:
  act=['Read your recorded results from checkpoints 1-4 aloud.','Divide the final candidates between players. Point to each required field on each candidate.','Cross out any candidate with a mismatched field. Everyone reports one check; agree on the remaining choice.','Recorder writes the choice and two earlier clues proving it. Show both sources to your adult.']
 else:
  act=['Reader reads each printed condition separately. Investigator points to that feature on every candidate.','Use the previous result wherever the mission asks for it. Do not choose from the illustration alone.','Checker marks a pencil X beside each candidate failing any condition. Erase an X if the team finds a mistake.','Recorder writes the surviving choice and its outgoing code/place/message. Each player explains one match or rejection.']
 return act

