def footer(c,d):
 w,h=d.pagesize;c.setFillColor(g.BLUE);c.rect(0,h-37,w,37,fill=1,stroke=0);c.setFillColor(g.NAVY);c.setFont('ArialBold',8);c.drawString(44,h-23,'PAPER ADVENTURE / '+d.game_id.upper()+' / '+d.setting.upper());c.setFont('Arial',8);c.drawString(44,28,f'{d.role.upper()} / Edition 1.0 / {d.paper}');c.drawRightString(w-44,28,f'Page {d.page}');c.setStrokeColor(g.LINE);c.line(44,42,w-44,42)

def build(s,paper,size):
 w=size[0]-88
 if s['id']=='dinosaur' and s['setting']=='home':
  import dinosaur_home_experience as dino
  pp=dino.player(s,w)
 elif s['id']=='space' and s['setting']=='home':
  import space_home_control_room as space
  pp=space.player(s,w)
 elif s['id']=='forest' and s['setting']=='home':
  import forest_post_office as forest
  pp=forest.player(s,w)
 elif s['id']=='halloween' and s['setting']=='home':
  import halloween_paper_theatre as halloween
  pp=halloween.player(s,w)
 else: pp=player(s,w)
 labels=[]
 for i in range(5):
  hits=[j+1 for j,p in enumerate(pp) if any(f'CHECKPOINT {i+1} /' in getattr(el,'text','') for el in p)]
  labels.append(', '.join(map(str,hits)))
 manifest=[]
 gp=dino.guide(s,w,dict(player=len(pp),stages=labels),guide) if s['id']=='dinosaur' and s['setting']=='home' else guide(s,w,dict(player=len(pp),stages=labels))
 if s['id']=='space' and s['setting']=='home':gp=space.guide(s,w,dict(player=len(pp),stages=labels),guide)
 if s['id']=='forest' and s['setting']=='home':gp=forest.guide(s,w,dict(player=len(pp),stages=labels),guide)
 if s['id']=='halloween' and s['setting']=='home':gp=halloween.guide(s,w,dict(player=len(pp),stages=labels),guide)
 for role,pages in [('player',pp),('guide',gp)]:
  path=OUT/f"{s['id']}-{s['setting']}-{role}-1.0-{paper}.pdf";doc=SimpleDocTemplate(str(path),pagesize=size,leftMargin=44,rightMargin=44,topMargin=60,bottomMargin=55,title=s['title']+' / '+role,author='Paper Adventure Workshop');doc.game_id=s['id'];doc.setting=s['setting'];doc.role=role;doc.paper=paper
  flow=[]
  for i,p in enumerate(pages):
   if i:flow.append(PageBreak())
   flow+=p
  doc.build(flow,onFirstPage=footer,onLaterPages=footer)
  r=PdfReader(path);assert len(r.pages)==len(pages),(path,len(r.pages),len(pages))
  content=' '.join(p.extract_text() or '' for p in r.pages)
  assert not re.search(r'internal|draft|not play.tested|do not sell|unpublished',content,re.I),path
  manifest.append(dict(world=s['id'],setting=s['setting'],paper=paper,role=role,path=path.relative_to(ROOT).as_posix(),pages=len(r.pages),bytes=path.stat().st_size,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),r2Key=f"retail/{s['id']}/{s['setting']}/1.0/{paper}/{role}-{hashlib.sha256(path.read_bytes()).hexdigest()[:16]}.pdf"))
 return manifest

def celebration_home():
 import generate_celebration_home_v04 as c
 items=[]
 for paper,size in [('A4',g.A4),('Letter',g.letter)]:
  for role,builder in [('player',c.player),('guide',c.guide)]:
   pages=builder(size[0]-88)
   for content in pages:
    for i,el in enumerate(content):
     if hasattr(el,'text'):
      t=el.text.replace('v0.4','Edition 1.0')
      t=re.sub(r'This version has been checked.*?play-tested\.', '', t)
      t=re.sub(r'real-family feedback is still needed to assess fun and difficulty\.', 'keep the five numbered piles together for your next session.',t)
      t=t.replace('These support options have no extra printing and are not validated difficulty bands or play-time promises.','Choose support according to reading confidence; no extra printing is needed.')
      content[i]=g.p(t,el.style.name if el.style.name in g.STYLES else 'body')
   path=OUT/f'celebration-home-{role}-1.0-{paper}.pdf'
   d=SimpleDocTemplate(str(path),pagesize=size,leftMargin=44,rightMargin=44,topMargin=60,bottomMargin=55,title='The Missing Birthday Chest / '+role,author='Paper Adventure Workshop');d.game_id='celebration';d.setting='home';d.role=role;d.paper=paper
   flow=[]
   for i,content in enumerate(pages):
    if i:flow.append(PageBreak())
    flow+=content
   d.build(flow,onFirstPage=footer,onLaterPages=footer)
   r=PdfReader(path);assert len(r.pages)==len(pages),(path,len(r.pages))
   t=' '.join(p.extract_text() or '' for p in r.pages);assert not re.search(r'internal|draft|not play.tested|unpublished',t,re.I)
   items.append(dict(world='celebration',setting='home',paper=paper,role=role,path=path.relative_to(ROOT).as_posix(),pages=len(r.pages),bytes=path.stat().st_size,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),r2Key=f'retail/celebration/home/1.0/{paper}/{role}-{hashlib.sha256(path.read_bytes()).hexdigest()[:16]}.pdf'))
 return items

def main():
 items=[]
 for s in json.loads((ROOT/'content/theme-design/retail-games-v1.json').read_text()):
  normalise(s)
  for paper,size in [('A4',g.A4),('Letter',g.letter)]:items+=build(s,paper,size)
 (OUT/'retail-packs-1.0-manifest.json').write_text(json.dumps(dict(version='1.0',items=items),indent=2)+'\n')
 items+=celebration_home()
 (OUT/'retail-packs-1.0-manifest.json').write_text(json.dumps(dict(version='1.0',items=items),indent=2)+'\n')
 for s in {(x['world'],x['setting'],x['paper']) for x in items}:
  with zipfile.ZipFile(OUT/('-'.join(s)+'-complete-1.0.zip'),'w',zipfile.ZIP_DEFLATED) as z:
   for x in items:
    if (x['world'],x['setting'],x['paper'])==s:z.write(ROOT/x['path'],Path(x['path']).name)
 print('Built',len(items),'retail PDFs')

if __name__=='__main__':main()


